import { describe, it, expect, vi, beforeEach } from 'vitest';
import { registerUser } from '../actions/auth-actions';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';

// Mock dependencies
vi.mock('@/lib/prisma', () => ({
    prisma: {
        user: {
            findUnique: vi.fn(),
            create: vi.fn(),
        },
    },
}));

vi.mock('bcryptjs', () => ({
    default: {
        hash: vi.fn(),
    },
}));

describe('registerUser', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        global.fetch = vi.fn().mockResolvedValue({
            json: vi.fn().mockResolvedValue({ success: true })
        } as any);
    });

    it('debería retornar error para datos inválidos', async () => {
        const formData = new FormData();
        formData.append('cf-turnstile-response', 'valid-token');
        formData.append('email', 'not-an-email');
        formData.append('password', '123'); // Too short
        formData.append('name', '');

        const result = await registerUser(formData);

        expect(result.success).toBe(false);
        expect(result.errors).toBeDefined();
    });

    it('debería retornar error si el usuario ya existe', async () => {
        vi.mocked(prisma.user.findUnique).mockResolvedValueOnce({ id: '1', email: 'test@example.com' } as any);

        const formData = new FormData();
        formData.append('cf-turnstile-response', 'valid-token');
        formData.append('email', 'test@example.com');
        formData.append('password', 'password123');
        formData.append('name', 'Test User');

        const result = await registerUser(formData);

        expect(result.success).toBe(false);
        expect(result.errors?.email).toContain('El correo electrónico ya está registrado');
        expect(prisma.user.create).not.toHaveBeenCalled();
    });

    it('debería crear el usuario exitosamente', async () => {
        vi.mocked(prisma.user.findUnique).mockResolvedValueOnce(null);
        vi.mocked(bcrypt.hash).mockResolvedValueOnce('hashed-password' as never);
        vi.mocked(prisma.user.create).mockResolvedValueOnce({ id: '1' } as any);

        const formData = new FormData();
        formData.append('cf-turnstile-response', 'valid-token');
        formData.append('email', 'new@example.com');
        formData.append('password', 'password123');
        formData.append('name', 'New User');

        const result = await registerUser(formData);

        expect(result.success).toBe(true);
        expect(bcrypt.hash).toHaveBeenCalledWith('password123', 10);
        expect(prisma.user.create).toHaveBeenCalledWith({
            data: {
                email: 'new@example.com',
                password: 'hashed-password',
                name: 'New User',
                role: 'USER',
            },
        });
    });

    it('debería manejar errores de base de datos', async () => {
        vi.mocked(prisma.user.findUnique).mockResolvedValueOnce(null);
        vi.mocked(bcrypt.hash).mockResolvedValueOnce('hashed_pw' as never);
        vi.mocked(prisma.user.create).mockRejectedValueOnce(new Error('DB Error'));

        const formData = new FormData();
        formData.append('cf-turnstile-response', 'valid-token');
        formData.append('email', 'error@example.com');
        formData.append('password', 'password123');
        formData.append('name', 'Error User');

        const result = await registerUser(formData);

        expect(result.success).toBe(false);
        expect(result.message).toContain('Error al crear el usuario');
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { upsertProduct, searchProducts } from '../actions/product-actions';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';

// Mock dependencies
// Mock dependencies
vi.mock('@/lib/prisma', () => ({
    prisma: {
        product: {
            create: vi.fn(),
            update: vi.fn(),
            findMany: vi.fn(),
            findUnique: vi.fn(),
            delete: vi.fn(),
        },
        flavor: {
            findMany: vi.fn(),
        },
        $transaction: vi.fn(),
    },
}));

vi.mock('next/cache', () => ({
    revalidatePath: vi.fn(),
}));

describe('upsertProduct', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería crear un producto exitosamente', async () => {
        const formData = new FormData();
        formData.append('name', 'New Product');
        formData.append('description', 'A great product');
        formData.append('price', '100');
        formData.append('stock', '10');
        formData.append('slug', 'new-product');
        formData.append('image', 'https://example.com/image.jpg');
        formData.append('isActive', 'on');

        const result = await upsertProduct(null, formData);

        expect(result.success).toBe(true);
        expect(prisma.product.create).toHaveBeenCalledWith({
            data: {
                name: 'New Product',
                description: 'A great product',
                price: 100,
                stock: 10,
                slug: 'new-product',
                image: 'https://example.com/image.jpg',
                isActive: true,
                flavors: {
                    create: [],
                },
            },
        });
        expect(revalidatePath).toHaveBeenCalledWith('/admin/productos');
        expect(revalidatePath).toHaveBeenCalledWith('/productos');
    });

    it('debería editar un producto exitosamente', async () => {
        const formData = new FormData();
        formData.append('id', '123');
        formData.append('name', 'Updated Product');
        formData.append('description', 'Updated description');
        formData.append('price', '200');
        formData.append('stock', '20');
        formData.append('slug', 'updated-product');
        formData.append('image', '');
        formData.append('isActive', 'on');

        const result = await upsertProduct(null, formData);

        expect(result.success).toBe(true);
        expect(prisma.product.update).toHaveBeenCalledWith({
            where: { id: 123 },
            data: {
                name: 'Updated Product',
                description: 'Updated description',
                price: 200,
                stock: 20,
                slug: 'updated-product',
                image: '',
                isActive: true,
                flavors: {
                    create: [],
                    deleteMany: {},
                },
            },
        });
        expect(revalidatePath).toHaveBeenCalledTimes(2);
    });

    it('debería fallar con errores de validación Zod', async () => {
        const formData = new FormData();
        formData.append('name', 'AB'); // Too short
        formData.append('description', '');
        formData.append('price', '-10'); // Negative
        formData.append('stock', '5');
        formData.append('slug', 'slug');
        formData.append('image', '');

        const result = await upsertProduct(null, formData);

        expect(result.success).toBe(false);
        expect(result.errors).toHaveProperty('name');
        expect(result.errors).toHaveProperty('price');
        expect(prisma.product.create).not.toHaveBeenCalled();
        expect(prisma.product.update).not.toHaveBeenCalled();
    });

    it('debería manejar errores de base de datos', async () => {
        const formData = new FormData();
        formData.append('name', 'Error Product');
        formData.append('description', 'Desc');
        formData.append('price', '100');
        formData.append('stock', '10');
        formData.append('slug', 'error-product');
        formData.append('image', '');
        formData.append('isActive', 'on');

        // Simulate DB error
        vi.mocked(prisma.product.create).mockRejectedValueOnce(new Error('DB Error'));

        const result = await upsertProduct(null, formData);

        expect(result.success).toBe(false);
        expect(result.message).toContain('Error al guardar en base de datos');
    });
});

describe('getProducts', () => {
    it('debería retornar productos con el precio como número', async () => {
        const mockProducts = [
            { id: 1, name: 'P1', price: { toNumber: () => 10.5 }, stock: 5 },
            { id: 2, name: 'P2', price: { toNumber: () => 20.0 }, stock: 10 },
        ];
        vi.mocked(prisma.product.findMany).mockResolvedValue(mockProducts as any);

        const { getProducts } = await import('../actions/product-actions');
        const result = await getProducts();

        expect(result).toHaveLength(2);
        expect(result[0].price).toBe(10.5);
        expect(result[1].price).toBe(20.0);
    });
});

describe('checkStock', () => {
    it('debería retornar el stock correcto', async () => {
        vi.mocked(prisma.product.findUnique).mockResolvedValue({ stock: 15 } as any);
        const { checkStock } = await import('../actions/product-actions');
        const stock = await checkStock(1);
        expect(stock).toBe(15);
    });

    it('debería retornar 0 si el producto no se encuentra', async () => {
        vi.mocked(prisma.product.findUnique).mockResolvedValue(null);
        const { checkStock } = await import('../actions/product-actions');
        const stock = await checkStock(999);
        expect(stock).toBe(0);
    });
});

describe('checkout', () => {
    it('debería fallar si el stock es insuficiente', async () => {
        // Mock checkStock behavior (findUnique)
        vi.mocked(prisma.product.findUnique).mockResolvedValue({ stock: 1 } as any);

        const { checkout } = await import('../actions/product-actions');
        const result = await checkout([{ productId: 1, quantity: 5 }]);

        expect(result.success).toBe(false);
        expect(result.message).toContain('Stock insuficiente');
    });

    it('debería tener éxito y actualizar el stock', async () => {
        vi.mocked(prisma.product.findUnique).mockResolvedValue({ stock: 100 } as any);
        vi.mocked(prisma.$transaction).mockResolvedValue([]);

        const { checkout } = await import('../actions/product-actions');
        const result = await checkout([{ productId: 1, quantity: 5 }]);

        expect(result.success).toBe(true);
        expect(prisma.$transaction).toHaveBeenCalled();
    });

    it('debería manejar errores durante el checkout', async () => {
        vi.mocked(prisma.product.findUnique).mockResolvedValue({ stock: 100 } as any);
        vi.mocked(prisma.$transaction).mockRejectedValue(new Error('Tx Failed'));

        const { checkout } = await import('../actions/product-actions');
        const result = await checkout([{ productId: 1, quantity: 5 }]);

        expect(result.success).toBe(false);
        expect(result.message).toContain('Error al procesar la compra');
    });
});

describe('deleteProduct', () => {
    it('debería eliminar el producto exitosamente', async () => {
        vi.mocked(prisma.product.delete).mockResolvedValue({} as any);
        const { deleteProduct } = await import('../actions/product-actions');
        const result = await deleteProduct(1);
        expect(result.success).toBe(true);
        expect(prisma.product.delete).toHaveBeenCalledWith({ where: { id: 1 } });
    });

    it('debería manejar errores al eliminar', async () => {
        vi.mocked(prisma.product.delete).mockRejectedValue(new Error('Delete invalid'));
        const { deleteProduct } = await import('../actions/product-actions');
        const result = await deleteProduct(1);
        expect(result).not.toHaveProperty('success');
        expect(result.message).toBe('No se pudo eliminar el producto');
    });
});

describe('getFlavors', () => {
    it('debería retornar sabores', async () => {
        const mockFlavors = [{ id: 1, name: 'Vainilla' }];
        vi.mocked(prisma.flavor.findMany).mockResolvedValue(mockFlavors as any);
        const { getFlavors } = await import('../actions/product-actions');
        const result = await getFlavors();
        expect(result).toEqual(mockFlavors);
    });
});

describe('searchProducts', () => {

    beforeEach(() => {
        vi.clearAllMocks();
    })
    it('debería retornar un array vacío si la query está vacía o tiene menos de 3 caracteres', async () => {
        expect(await searchProducts('')).toEqual([]);
        expect(await searchProducts('ab')).toEqual([]);

        // Verificamos que Prisma no fue llamado innecesariamente
        expect(prisma.product.findMany).not.toHaveBeenCalled();
    });

    it('debería llamar a la base de datos y formatear correctamente los productos encontrados', async () => {
        const mockPrismaProducts = [
            {
                id: '1',
                name: 'Galleta de Chocolate',
                slug: 'galleta-de-chocolate',
                price: { toNumber: () => 15.50 },
                image: 'chocolate.jpg',
                flavors: [
                    { flavor: { name: 'Chocolate' } },
                    { flavor: { name: 'Vainilla' } },
                ],
            },
        ];

        // Usamos vi.mocked para mantener tu estilo de mocks
        vi.mocked(prisma.product.findMany).mockResolvedValue(mockPrismaProducts as any);

        const query = 'choco';
        const limit = 5;
        const result = await searchProducts(query, limit);

        expect(prisma.product.findMany).toHaveBeenCalledWith({
            where: {
                isActive: true,
                OR: [
                    { name: { contains: query } },
                    { flavors: { some: { flavor: { name: { contains: query } } } } },
                ],
            },
            take: limit,
            include: {
                flavors: {
                    include: { flavor: true },
                },
            },
        });

        expect(result).toEqual([
            {
                id: '1',
                name: 'Galleta de Chocolate',
                slug: 'galleta-de-chocolate',
                price: 15.50,
                flavorText: 'Chocolate, Vainilla',
                image: 'chocolate.jpg',
            },
        ]);
    });

    it('debería capturar errores, loguearlos en consola y retornar un array vacío', async () => {
        const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => { });
        const dbError = new Error('Error de conexión');

        vi.mocked(prisma.product.findMany).mockRejectedValueOnce(dbError);

        const result = await searchProducts('galleta');

        expect(consoleSpy).toHaveBeenCalledWith("Error buscando productos:", dbError);
        expect(result).toEqual([]);

        consoleSpy.mockRestore(); // Limpiamos el espía
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { getStores, upsertStore, deleteStore } from '../actions/store-actions';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';

// Mock dependencies
vi.mock('@/lib/prisma', () => ({
    prisma: {
        store: {
            findMany: vi.fn(),
            create: vi.fn(),
            update: vi.fn(),
            delete: vi.fn(),
        },
    },
}));

vi.mock('next/cache', () => ({
    revalidatePath: vi.fn(),
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function buildFormData(fields: Record<string, string>) {
    const formData = new FormData();
    for (const [key, value] of Object.entries(fields)) {
        formData.append(key, value);
    }
    return formData;
}

const validStoreFields = {
    name: 'Sucursal Centro',
    address: 'Av. Principal 123',
    schedule: 'Lun-Vie 9am-6pm',
    latitude: '19.4326',
    longitude: '-99.1332',
    phone: '5551234567',
    isActive: 'on',
};

// ---------------------------------------------------------------------------
// getStores
// ---------------------------------------------------------------------------
describe('getStores', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería retornar la lista de tiendas ordenada por fecha de creación', async () => {
        const mockStores = [
            { id: '1', name: 'Tienda A', createdAt: new Date() },
            { id: '2', name: 'Tienda B', createdAt: new Date() },
        ];
        vi.mocked(prisma.store.findMany).mockResolvedValueOnce(mockStores as any);

        const result = await getStores();

        expect(result).toEqual(mockStores);
        expect(prisma.store.findMany).toHaveBeenCalledWith({
            orderBy: { createdAt: 'desc' },
        });
    });

    it('debería retornar un arreglo vacío si no hay tiendas', async () => {
        vi.mocked(prisma.store.findMany).mockResolvedValueOnce([]);

        const result = await getStores();

        expect(result).toEqual([]);
    });
});

// ---------------------------------------------------------------------------
// upsertStore – validación
// ---------------------------------------------------------------------------
describe('upsertStore – validación', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería retornar error si el nombre es demasiado corto', async () => {
        const formData = buildFormData({ ...validStoreFields, name: 'AB' });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.errors).toHaveProperty('name');
        expect(prisma.store.create).not.toHaveBeenCalled();
    });

    it('debería retornar error si la dirección es demasiado corta', async () => {
        const formData = buildFormData({ ...validStoreFields, address: 'Cor' });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.errors).toHaveProperty('address');
        expect(prisma.store.create).not.toHaveBeenCalled();
    });

    it('debería retornar error si la latitud no es un número válido', async () => {
        const formData = buildFormData({ ...validStoreFields, latitude: 'no-es-numero' });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.errors).toHaveProperty('latitude');
        expect(prisma.store.create).not.toHaveBeenCalled();
    });

    it('debería retornar error si la longitud no es un número válido', async () => {
        const formData = buildFormData({ ...validStoreFields, longitude: 'abc' });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.errors).toHaveProperty('longitude');
    });

    it('debería incluir el mensaje de error correcto al fallar la validación', async () => {
        const formData = buildFormData({ ...validStoreFields, name: 'X' });

        const result = await upsertStore(null, formData);

        expect(result.message).toBe('Error en los datos enviados');
    });
});

// ---------------------------------------------------------------------------
// upsertStore – creación
// ---------------------------------------------------------------------------
describe('upsertStore – creación', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería crear una tienda exitosamente', async () => {
        vi.mocked(prisma.store.create).mockResolvedValueOnce({} as any);
        const formData = buildFormData(validStoreFields);

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(true);
        expect(result.message).toBe('Sucursal guardada correctamente');
        expect(prisma.store.create).toHaveBeenCalledWith({
            data: {
                name: 'Sucursal Centro',
                address: 'Av. Principal 123',
                schedule: 'Lun-Vie 9am-6pm',
                latitude: 19.4326,
                longitude: -99.1332,
                phone: '5551234567',
                isActive: true,
            },
        });
        expect(revalidatePath).toHaveBeenCalledWith('/admin/tiendas');
    });

    it('debería marcar isActive como false cuando no se envía el checkbox', async () => {
        vi.mocked(prisma.store.create).mockResolvedValueOnce({} as any);
        // isActive ausente → formData.get("isActive") !== "on" → false
        const { isActive, ...rest } = validStoreFields;
        const formData = buildFormData(rest);

        await upsertStore(null, formData);

        expect(prisma.store.create).toHaveBeenCalledWith(
            expect.objectContaining({
                data: expect.objectContaining({ isActive: false }),
            }),
        );
    });

    it('debería manejar errores de base de datos al crear', async () => {
        vi.mocked(prisma.store.create).mockRejectedValueOnce(new Error('DB Error'));
        const formData = buildFormData(validStoreFields);

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.message).toBe('Error al guardar en base de datos.');
        expect(revalidatePath).not.toHaveBeenCalled();
    });
});

// ---------------------------------------------------------------------------
// upsertStore – edición
// ---------------------------------------------------------------------------
describe('upsertStore – edición', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería editar una tienda existente exitosamente', async () => {
        vi.mocked(prisma.store.update).mockResolvedValueOnce({} as any);
        const formData = buildFormData({ id: 'store-42', ...validStoreFields });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(true);
        expect(prisma.store.update).toHaveBeenCalledWith({
            where: { id: 'store-42' },
            data: expect.objectContaining({ name: 'Sucursal Centro' }),
        });
        expect(prisma.store.create).not.toHaveBeenCalled();
        expect(revalidatePath).toHaveBeenCalledWith('/admin/tiendas');
    });

    it('debería manejar errores de base de datos al editar', async () => {
        vi.mocked(prisma.store.update).mockRejectedValueOnce(new Error('DB Error'));
        const formData = buildFormData({ id: 'store-99', ...validStoreFields });

        const result = await upsertStore(null, formData);

        expect(result.success).toBe(false);
        expect(result.message).toBe('Error al guardar en base de datos.');
    });
});

// ---------------------------------------------------------------------------
// deleteStore
// ---------------------------------------------------------------------------
describe('deleteStore', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('debería eliminar una tienda exitosamente', async () => {
        vi.mocked(prisma.store.delete).mockResolvedValueOnce({} as any);

        const result = await deleteStore('store-1');

        expect(result.success).toBe(true);
        expect(prisma.store.delete).toHaveBeenCalledWith({ where: { id: 'store-1' } });
        expect(revalidatePath).toHaveBeenCalledWith('/admin/tiendas');
    });

    it('debería retornar mensaje de error si la eliminación falla', async () => {
        vi.mocked(prisma.store.delete).mockRejectedValueOnce(new Error('Delete failed'));

        const result = await deleteStore('store-bad');

        expect(result).not.toHaveProperty('success');
        expect(result.message).toBe('No se pudo eliminar la sucursal');
        expect(revalidatePath).not.toHaveBeenCalled();
    });
});

'use server';

import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { z } from 'zod';

const RegisterSchema = z.object({
  email: z.string().email(),
  password: z.string().min(6),
  name: z.string(),
});

// Función auxiliar para validar con Cloudflare
async function verifyTurnstileToken(token: string) {
  const res = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `secret=${process.env.TURNSTILE_SECRET_KEY}&response=${token}`,
  });
  const data = await res.json();
  return data.success;
}

export async function registerUser(formData: FormData) {
  const data = Object.fromEntries(formData);
  const parsed = RegisterSchema.safeParse(data);
  const token = formData.get('cf-turnstile-response') as string;

  if (!token) {
    return { error: 'Por favor, completa la validación de seguridad (Captcha).' };
  }

  const isValidToken = await verifyTurnstileToken(token);
  if (!isValidToken) {
    return { error: 'Validación de seguridad fallida. Intenta nuevamente.' };
  }

  if (!parsed.success) {
    return {
      success: false,
      errors: parsed.error.flatten().fieldErrors
    };
  }

  const { email, password, name } = parsed.data;

  // Verificar si existe
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) {
    return {
      success: false,
      errors: { email: ['El correo electrónico ya está registrado'] }
    };
  }

  // Crear hash
  const hashedPassword = await bcrypt.hash(password, 10);

  // Crear usuario
  try {
    await prisma.user.create({
      data: {
        email,
        password: hashedPassword,
        name,
        role: 'USER',
      },
    });
    return { success: true };
  } catch (error) {
    return {
      success: false,
      message: 'Error al crear el usuario en la base de datos'
    };
  }
}

'use server';

import { contactSchema } from "@/lib/validators/contact-schema";

interface ContactResult {
  success: boolean;
  message?: string;
  errors?: {
    name?: string[];
    email?: string[];
    message?: string[];
  };
}

export async function sendContactMessage(prevState: any, formData: FormData): Promise<ContactResult> {
  // Extraer datos
  const rawData = {
    name: formData.get('name'),
    email: formData.get('email'),
    message: formData.get('message'),
  };

  // Validar con Zod
  const validatedFields = contactSchema.safeParse(rawData);

  // Si hay errores de validación
  if (!validatedFields.success) {
    return {
      success: false,
      errors: validatedFields.error.flatten().fieldErrors,
      message: 'Por favor corrige los errores en el formulario'
    };
  }

  // Datos válidos
  const { name, email, message } = validatedFields.data;

  try {
    // Simular procesamiento del mensaje

    console.log('💬 Nuevo mensaje de contacto validado:');
    console.log('👤 Nombre:', name);
    console.log('📧 Email:', email);
